CREATE TABLE IF NOT EXISTS payment_orphans (
  id TEXT PRIMARY KEY,
  invoice_id TEXT NOT NULL,
  amount_cents INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  reason TEXT NOT NULL
);

INSERT OR IGNORE INTO payment_orphans (
  id,
  invoice_id,
  amount_cents,
  created_at,
  reason
)
SELECT
  p.id,
  p.invoice_id,
  p.amount_cents,
